css:
.eq{display:block; text-align:center; margin:10px 0; color:#ea4b93}
.eq::before{content:"="}
.amp{font-family:Georgia,serif; font-size:46px; line-height:1; color:#f3e3cd}
.label{letter-spacing:.3em; font-size:11px; color:#5B7F6B}
.label::before{content:"（ "} .label::after{content:" ）"}
h2 span{border-bottom:2px dashed #cdd6d0; padding-bottom:.4em}
.emph{-webkit-text-emphasis:dot #8aa89b; text-emphasis:dot #8aa89b; text-emphasis-position:over right}
